//! Polynomial coefficients generated by the project's minimax tool (D-10.3): each file in
//! `coeffs/` is the output of `cargo xtask remez` on a fit file in `crates/math/fits/`, with its
//! derivation (target, interval, iterations, error bound before and after rounding) in its header.
//! `cargo xtask remez --check crates/math/fits/*.fit` regenerates them and fails on any
//! difference.
//!
//! The two examples demonstrate and pin down the tool (milestone 1 of Track M); the elementary
//! functions (milestone 2) add their own fits and use them.

#![allow(dead_code)] // the examples are used by the tests until the elementary functions arrive

pub(crate) mod example_exp;
pub(crate) mod example_sin;
pub(crate) mod tables;

#[cfg(test)]
#[allow(clippy::indexing_slicing, clippy::arithmetic_side_effects, clippy::as_conversions, clippy::float_cmp)]
mod tests {
    use super::example_exp::EXAMPLE_EXP;
    use super::example_sin::EXAMPLE_SIN;

    fn horner(c: &[u64], x: f64) -> f64 {
        c.iter().rev().fold(0.0, |acc, &b| acc.mul_add(x, f64::from_bits(b)))
    }

    #[test]
    fn example_fits_approximate_their_targets() {
        // expm1(x) = x q(x) on [-ln2/2, ln2/2]; sin(x) = sum c_k x^(2k+1) on [-pi/4, pi/4]. The
        // host's own functions are within an ulp or two, the fits' error bounds well under one.
        for i in -100..=100 {
            let x = f64::from(i) / 100.0 * core::f64::consts::LN_2 / 2.0;
            let p = x * horner(&EXAMPLE_EXP, x);
            assert!((p - x.exp_m1()).abs() <= 4.0 * f64::EPSILON * x.exp_m1().abs().max(f64::MIN_POSITIVE), "expm1 {x}");
            let y = f64::from(i) / 100.0 * core::f64::consts::FRAC_PI_4;
            let x2 = y * y;
            let s = y * EXAMPLE_SIN.iter().rev().fold(0.0, |acc: f64, &b| acc.mul_add(x2, f64::from_bits(b)));
            assert!((s - y.sin()).abs() <= 4.0 * f64::EPSILON * y.sin().abs().max(f64::MIN_POSITIVE), "sin {y}");
        }
    }
}
